+	for (i = 0; i < SSIC_PORT_NUM; i++) {
+		void __iomem *reg = base + offset + SSIC_ACCESS_CTRL +
+				    i * SSIC_ACCESS_CTRL_OFFSET;
+		u32 val = readl(reg);
