 drivers/usb/core/message.c  | 74 ++++++++++++++++++++++++++++++++++++++++++++-
 drivers/usb/core/usb.h      |  2 ++
 drivers/usb/host/xhci-mem.c | 18 +++++++++--
 drivers/usb/host/xhci.c     |  4 +++
 include/linux/usb.h         |  7 +++++
 6 files changed, 117 insertions(+), 4 deletions(-)

